"use client";

import React from "react";
import { Navbar, type NavbarProps } from "./navbar";
import { Hero, type HeroProps } from "./hero";
import { Features, type FeaturesProps } from "./features";
import { Showcase, type ShowcaseProps } from "./showcase";
import { Pricing, type PricingProps } from "./pricing";
import { Testimonials, type TestimonialsProps } from "./testimonials";
import { FAQ, type FaqProps } from "./faq";
import { CTA, type CtaProps } from "./cta";
import { Footer, type FooterProps } from "./footer";
import { cn } from "@/lib/utils";

export {
  Navbar,
  Hero,
  Features,
  Showcase,
  Pricing,
  Testimonials,
  FAQ,
  CTA,
  Footer,
};

export interface AILandingPageProps {
  navbarProps?: NavbarProps;
  heroProps?: HeroProps;
  featuresProps?: FeaturesProps;
  showcaseProps?: ShowcaseProps;
  pricingProps?: PricingProps;
  testimonialsProps?: TestimonialsProps;
  faqProps?: FaqProps;
  ctaProps?: CtaProps;
  footerProps?: FooterProps;
  previewMode?: boolean;
  defaultExpanded?: boolean;
}

/**
 * AI Landing Page Template
 */
export default function AILandingPage({
  navbarProps,
  heroProps,
  featuresProps,
  showcaseProps,
  pricingProps,
  testimonialsProps,
  faqProps,
  ctaProps,
  footerProps,
  previewMode = false,
  defaultExpanded = false,
}: AILandingPageProps) {
  return (
    <div className={cn("relative min-h-screen w-full bg-white p-2 sm:p-3 md:p-3 lg:p-3 font-sans text-zinc-900 antialiased selection:bg-zinc-800 selection:text-white transition-colors duration-300", previewMode && "max-h-[480px] overflow-hidden p-2")}>
      <div className="relative mx-auto flex w-full max-w-[100rem] flex-col overflow-hidden rounded-[1.5rem] sm:rounded-[2rem] bg-white shadow-2xl ring-1 ring-zinc-200/50 transition-colors duration-300">
        <Hero
          {...heroProps}
        />

        {!previewMode && (
          <>
            <Features {...featuresProps} />
            <Showcase {...showcaseProps} />
            <Pricing {...pricingProps} />
            <Testimonials {...testimonialsProps} />
            <FAQ {...faqProps} />
            <CTA {...ctaProps} />
            <Footer {...footerProps} />
          </>
        )}
      </div>
    </div>
  );
}

"use client";

import React, { useState, useEffect } from "react";
import { Menu, X, ArrowUpRight } from "lucide-react";
import { cn } from "@/lib/utils";

export interface NavItem {
  label: string;
  href: string;
}

export interface NavbarProps {
  logoText?: string;
  navItems?: NavItem[];
  ctaText?: string;
  onCtaClick?: () => void;
}

export function Navbar({
  logoText = "Aether AI",
  navItems = [
    { label: "Home", href: "#" },
    { label: "Features", href: "#features" },
    { label: "Pricing", href: "#pricing" },
  ],
  ctaText = "Get Started",
  onCtaClick,
}: NavbarProps) {
  const [scrolled, setScrolled] = useState(false);
  const [isOpen, setIsOpen] = useState(false);

  useEffect(() => {
    const handleScroll = () => {
      if (window.scrollY > 40) {
        setScrolled(true);
      } else {
        setScrolled(false);
      }
    };

    handleScroll();
    window.addEventListener("scroll", handleScroll, { passive: true });
    return () => window.removeEventListener("scroll", handleScroll);
  }, []);

  return (
    <header className="fixed top-0 left-0 right-0 z-50 flex justify-center pointer-events-none px-4 sm:px-6">
      <div
        className={cn(
          "pointer-events-auto relative z-50 flex items-center justify-between w-full transition-all duration-500 ease-[cubic-bezier(0.22,1,0.36,1)]",
          scrolled
            ? "mt-3 sm:mt-4 max-w-3xl rounded-full px-5 sm:px-7 py-2 sm:py-2.5 bg-black/35 backdrop-blur-2xl border border-white/15 shadow-[0_8px_32px_0_rgba(0,0,0,0.25)]"
            : "mt-0 max-w-7xl rounded-none px-2 sm:px-4 py-5 sm:py-6 bg-transparent border border-transparent shadow-none"
        )}
      >
        {/* Logo (Stylish White Cursive Text Only) */}
        <div className="flex items-center cursor-pointer group">
          <span className="font-instrument italic font-normal text-2xl tracking-normal text-white transition-colors">
            {logoText}
          </span>
        </div>

        {/* Desktop Nav */}
        <div className="hidden md:flex items-center gap-8">
          {navItems.map((item) => (
            <a
              key={item.label}
              href={item.href}
              className="text-white/90 hover:text-white text-sm font-medium transition-colors"
            >
              {item.label}
            </a>
          ))}
        </div>

        {/* CTA Button & Mobile Toggle */}
        <div className="flex items-center gap-4">
          <button
            onClick={onCtaClick}
            className="group relative hidden md:flex items-center gap-2 cursor-pointer transition-all duration-300 text-white px-5 py-2 rounded-full text-sm font-semibold hover:scale-105 border border-[#0f0f0f] bg-gradient-to-b from-[#2d2d2d] to-[#171717] hover:from-[#363636] hover:to-[#202020] shadow-[inset_0_1px_1px_rgba(255,255,255,0.5),0_4px_12px_rgba(0,0,0,0.3)]"
          >
            {ctaText}
            <span className="flex items-center justify-center w-5 h-5 rounded-full bg-white/10 group-hover:bg-white/20 transition-colors shadow-[inset_0_1px_1px_rgba(255,255,255,0.4)]">
              <ArrowUpRight className="h-3 w-3 text-white" strokeWidth={2.5} />
            </span>
          </button>

          {/* Mobile Menu Toggle */}
          <button
            onClick={() => setIsOpen(!isOpen)}
            aria-label="Toggle Menu"
            className="flex md:hidden items-center justify-center w-9 h-9 rounded-full bg-white/10 text-white hover:bg-white/20 transition-colors border border-white/10"
          >
            {isOpen ? <X className="h-5 w-5" /> : <Menu className="h-5 w-5" />}
          </button>
        </div>

        {/* Mobile Drawer */}
        <div
          className={cn(
            "absolute top-full left-0 right-0 mt-2 z-40 md:hidden overflow-hidden transition-all duration-300 ease-in-out rounded-2xl bg-black/80 backdrop-blur-2xl border border-white/15 shadow-2xl",
            isOpen ? "max-h-64 opacity-100 p-5" : "max-h-0 opacity-0 p-0 border-0 pointer-events-none"
          )}
        >
          <div className="flex flex-col gap-3">
            {navItems.map((item) => (
              <a
                key={item.label}
                href={item.href}
                onClick={() => setIsOpen(false)}
                className="text-base font-medium text-white/90 hover:text-white transition-colors"
              >
                {item.label}
              </a>
            ))}
            <button
              onClick={() => {
                setIsOpen(false);
                onCtaClick?.();
              }}
              className="group relative flex items-center justify-center gap-2 transition-all duration-300 text-white px-5 py-2.5 mt-2 rounded-full text-sm font-semibold border border-[#0f0f0f] bg-gradient-to-b from-[#2d2d2d] to-[#171717] hover:from-[#363636] hover:to-[#202020] shadow-[inset_0_1px_1px_rgba(255,255,255,0.5),0_4px_12px_rgba(0,0,0,0.3)] w-full"
            >
              {ctaText}
              <span className="flex items-center justify-center w-5 h-5 rounded-full bg-white/10 group-hover:bg-white/20 transition-colors shadow-[inset_0_1px_1px_rgba(255,255,255,0.4)]">
                <ArrowUpRight className="h-3 w-3 text-white" strokeWidth={2.5} />
              </span>
            </button>
          </div>
        </div>
      </div>
    </header>
  );
}

"use client";

import React from "react";
import { motion, Variants } from "motion/react";
import { Workflow, Database, BarChart3, Zap, MoreHorizontal } from "lucide-react";
import { Schibsted_Grotesk } from "next/font/google";
import { cn } from "@/lib/utils";
import { GlassInput } from "./glass-input";
import { Navbar } from "./navbar";

const schibstedFont = Schibsted_Grotesk({
  subsets: ["latin"],
});

const titleContainerVariants: Variants = {
  hidden: { opacity: 0 },
  visible: {
    opacity: 1,
    transition: {
      staggerChildren: 0.08,
      delayChildren: 0.1,
    },
  },
};

const titleWordVariants: Variants = {
  hidden: { opacity: 0, y: 18, filter: "blur(4px)" },
  visible: {
    opacity: 1,
    y: 0,
    filter: "blur(0px)",
    transition: {
      duration: 0.45,
      ease: [0.2, 0.65, 0.3, 0.9] as const,
    },
  },
};

export interface HeroProps {
  badgeText?: string;
  titlePart1?: string;
  titlePart2?: string;
  chips?: { icon: React.ReactNode; label: string }[];
  placeholder?: string;
  logoText?: string;
  logos?: { name: string; icon: React.ReactNode }[];
  heroImageSrc?: string;
  heroImageAlt?: string;
}

export function Hero({
  // badgeText = "Automate your workflows with intelligent precision",
  titlePart1 = "Scale",
  titlePart2 = "automate\nwith intelligent logic.",
  chips = [
    { icon: <Workflow className="h-4 w-4" />, label: "Workflows" },
    { icon: <Database className="h-4 w-4" />, label: "Data" },
    { icon: <BarChart3 className="h-4 w-4" />, label: "Insights" },
    { icon: <Zap className="h-4 w-4" />, label: "Automation" },
    { icon: <MoreHorizontal className="h-4 w-4" />, label: "More" },
  ],
  placeholder = "Define your workflow...",
  heroImageSrc = "https://ik.imagekit.io/7k3exsyaa/heroSection.png",
  heroImageAlt = "AI Workspace Dashboard Preview",
}: HeroProps) {
  const fullTitle = `${titlePart1} ${titlePart2}`;
  const titleLines = fullTitle.split("\n");

  return (
    <>
      <style>{`
        @import url('https://fonts.googleapis.com/css2?family=Lastik&display=swap');
        @keyframes drift {
          0% { transform: translate(0, 0) scale(1); }
          33% { transform: translate(30px, -50px) scale(1.05); }
          66% { transform: translate(-20px, 20px) scale(0.95); }
          100% { transform: translate(0, 0) scale(1); }
        }
        @keyframes drift-reverse {
          0% { transform: translate(0, 0) scale(1); }
          33% { transform: translate(-30px, 50px) scale(1.05); }
          66% { transform: translate(20px, -20px) scale(0.95); }
          100% { transform: translate(0, 0) scale(1); }
        }
      `}</style>

      <div className="relative w-full min-h-[98vh] rounded-b-[32px] overflow-hidden bg-transparent flex flex-col font-sans">

        {/* Background Mesh Gradients, Background Image & Ribbon */}
        <div className="absolute inset-0 z-0 rounded-b-[32px] overflow-hidden pointer-events-none">
          {/* Hero Background Image */}
          {heroImageSrc && (
            <div className="absolute inset-0 z-0 flex items-center justify-center">
              <img
                src={heroImageSrc}
                alt={heroImageAlt}
                className="w-full h-full object-cover object-center opacity-100"
              />
            </div>
          )}

          {/* Subtle noise texture */}
          <div
            className="absolute inset-0 opacity-[0.02] mix-blend-overlay"
            style={{ backgroundImage: 'url("data:image/svg+xml,%3Csvg viewBox=%220 0 200 200%22 xmlns=%22http://www.w3.org/2000/svg%22%3E%3Cfilter id=%22noiseFilter%22%3E%3CfeTurbulence type=%22fractalNoise%22 baseFrequency=%220.8%22 numOctaves=%223%22 stitchTiles=%22stitch%22/%3E%3C/filter%3E%3Crect width=%22100%25%22 height=%22100%25%22 filter=%22url(%23noiseFilter)%22/%3E%3C/svg%3E")' }}
          />
        </div>

        {/* Navbar */}
        <Navbar />

        {/* Main Hero Content */}
        <div className="relative z-10 flex-1 flex flex-col items-center justify-center px-4 pt-20 sm:pt-24 mb-4">

          {/* Headline with Word-by-Word Reveal */}
          <motion.h1
            variants={titleContainerVariants}
            initial="hidden"
            animate="visible"
            style={{ fontFamily: "'Lastik', serif" }}
            className="text-center mb-8 pb-20 text-white text-4xl sm:text-5xl md:text-6xl lg:text-[4.5rem] tracking-tight leading-[1.05] max-w-4xl drop-shadow-[0_2px_10px_rgba(0,0,0,0.5)] font-normal"
          >
            {titleLines.map((line, lineIdx) => (
              <React.Fragment key={lineIdx}>
                {lineIdx > 0 && <br />}
                {line.split(" ").map((word, wordIdx) => (
                  <motion.span
                    key={`${lineIdx}-${wordIdx}`}
                    variants={titleWordVariants}
                    className="inline-block mr-[0.25em] text-white"
                  >
                    {word}
                  </motion.span>
                ))}
              </React.Fragment>
            ))}
          </motion.h1>

          <motion.p
            initial={{ opacity: 0, y: 20 }}
            animate={{ opacity: 1, y: 0 }}
            transition={{ delay: 0.15 }}
            className={cn(
              schibstedFont.className,
              "mt-4 text-center text-white/90 text-[15px] sm:text-[17px] max-w-lg font-medium tracking-tight leading-relaxed drop-shadow-[0_1px_8px_rgba(0,0,0,0.5)]"
            )}
          >
            The easiest way to build, deploy, and manage your autonomous agents. No complex coding required.
          </motion.p>

          {/* Glass Input Section */}
          <motion.div
            initial={{ opacity: 0, y: 30 }}
            animate={{ opacity: 1, y: 0 }}
            transition={{ delay: 0.25 }}
            className="relative w-full max-w-[720px] mt-5 sm:mt-8 px-4 sm:px-0"
          >
            <div className="relative z-10 drop-shadow-2xl">
              <GlassInput
                placeholder={placeholder}
                onSubmit={(val) => console.log("Submitted:", val)}
                showFilters={false}
              />
            </div>
          </motion.div>

        </div>

        {/* Trust / Logo Strip */}
        <motion.div
          initial={{ opacity: 0 }}
          animate={{ opacity: 1 }}
          transition={{ delay: 0.5, duration: 1 }}
          className="relative z-10 w-full pb-4 sm:pb-6 flex flex-col items-center mt-auto px-4"
        >

        </motion.div>

      </div>
    </>
  );
}

import * as React from "react"
import { Sparkles } from "lucide-react"

export interface GlassInputProps {
  placeholder?: string
  onSubmit?: (value: string) => void
  onFilterSelect?: (filter: string) => void
  showFilters?: boolean
}

export function GlassInput({
  placeholder = "A cat, orange fur, playful — chibi style",
  onSubmit,
}: GlassInputProps) {
  const [value, setValue] = React.useState("")

  const handleSubmit = (e: React.FormEvent) => {
    e.preventDefault()
    if (value.trim() && onSubmit) {
      onSubmit(value)
      setValue("")
    }
  }

  const handleKeyDown = (e: React.KeyboardEvent<HTMLTextAreaElement>) => {
    if (e.key === "Enter" && !e.shiftKey) {
      e.preventDefault()
      handleSubmit(e)
    }
  }

  return (
    <>
      <style>{`
        @keyframes border-slide {
          0% { background-position: 0% 50%; }
          100% { background-position: 200% 50%; }
        }
        @keyframes smoke-1 {
          0% { transform: translateX(-8px) translateY(0px) scale(1); opacity: 0.5; }
          50% { transform: translateX(8px) translateY(-2px) scale(1.1); opacity: 0.8; }
          100% { transform: translateX(-8px) translateY(0px) scale(1); opacity: 0.5; }
        }
        @keyframes smoke-2 {
          0% { transform: translateX(8px) translateY(0px) scale(1.1); opacity: 0.6; }
          50% { transform: translateX(-8px) translateY(-1px) scale(0.95); opacity: 0.9; }
          100% { transform: translateX(8px) translateY(0px) scale(1.1); opacity: 0.6; }
        }
        @keyframes smoke-3 {
          0% { transform: translateX(0px) translateY(1px) scale(0.95); opacity: 0.7; }
          50% { transform: translateX(12px) translateY(-1px) scale(1.1); opacity: 0.5; }
          100% { transform: translateX(0px) translateY(1px) scale(0.95); opacity: 0.7; }
        }
      `}</style>


      <div className="w-full max-w-[680px] mx-auto">
        {/* Input container wrapper to let glow bleed outside overflow-hidden */}
        <div className="relative w-full">
          {/* Animated subtle ambient glow under the input box (Preserved Rainbow Smoke) */}
          <div className="absolute left-1/2 -translate-x-1/2 -bottom-[4px] w-[88%] h-6 pointer-events-none z-0 opacity-70 group-hover:opacity-100 transition-opacity duration-700">
            {/* Base sliding glow */}
            <div
              className="absolute inset-0 rounded-full blur-[12px]"
              style={{
                background: 'linear-gradient(90deg, #f87171, #fbbf24, #a3e635, #38bdf8, #818cf8, #c084fc, #f472b6, #f87171)',
                backgroundSize: '200% 100%',
                animation: 'border-slide 6s linear infinite',
              }}
            />
            {/* Independent Smoke Wisps */}
            <div
              className="absolute left-[5%] top-1/2 -translate-y-1/2 w-[35%] h-[160%] rounded-full blur-[8px]"
              style={{
                background: 'linear-gradient(90deg, #fbbf24, #f87171)',
                animation: 'smoke-1 4s ease-in-out infinite',
              }}
            />
            <div
              className="absolute left-[35%] top-1/2 -translate-y-1/2 w-[30%] h-[140%] rounded-full blur-[8px]"
              style={{
                background: 'linear-gradient(90deg, #38bdf8, #a3e635)',
                animation: 'smoke-2 5s ease-in-out infinite',
              }}
            />
            <div
              className="absolute right-[10%] top-1/2 -translate-y-1/2 w-[35%] h-[160%] rounded-full blur-[8px]"
              style={{
                background: 'linear-gradient(90deg, #c084fc, #f472b6)',
                animation: 'smoke-3 4.5s ease-in-out infinite',
              }}
            />
          </div>


          <form
            onSubmit={handleSubmit}
            className="relative w-full rounded-[20px] bg-[#262220] p-4 sm:p-5 flex flex-col justify-between transition-all duration-300 shadow-[0_12px_40px_rgba(0,0,0,0.8)] group overflow-hidden z-10 border border-white/10"
          >
            {/* Subtle glass highlight border */}
            <div className="absolute inset-0 rounded-[20px] ring-1 ring-inset ring-white/10 pointer-events-none" />

            {/* The animated bottom border line inside the container (Rainbow) */}
            <div className="absolute bottom-0 left-8 right-8 h-[1px] z-20">
              <div
                className="absolute inset-0 opacity-70 transition-opacity duration-500 group-hover:opacity-100"
                style={{
                  background: 'linear-gradient(90deg, #f87171, #fbbf24, #a3e635, #38bdf8, #818cf8, #c084fc, #f472b6, #f87171)',
                  backgroundSize: '200% 100%',
                  animation: 'border-slide 6s linear infinite',
                  maskImage: 'linear-gradient(to right, transparent, black 15%, black 85%, transparent)',
                  WebkitMaskImage: 'linear-gradient(to right, transparent, black 15%, black 85%, transparent)'
                }}
              />
            </div>

            {/* TEXTAREA */}
            <textarea
              value={value}
              onChange={(e) => setValue(e.target.value)}
              onKeyDown={handleKeyDown}
              placeholder={placeholder}
              rows={1}
              className="w-full bg-transparent text-zinc-200 placeholder-zinc-400 text-[16px] font-normal outline-none resize-none pt-0.5 relative z-10 leading-relaxed tracking-normal min-h-[34px]"
            />

            {/* BOTTOM ROW SPACING */}
            <div className="flex items-center justify-end mt-3.5 relative z-10">
              {/* CUSTOMIZABLE: Generate Button Size & Padding (Adjust px-5 py-2, text-[15px]) */}
              <div className="p-1 rounded-[20px] bg-[#9A3B18]/60 border border-[#C84E20]/40 flex items-center justify-center">
                <button
                  type="submit"
                  className="flex items-center gap-2 px-5 py-2 rounded-[14px] bg-gradient-to-r from-[#FF6529] to-[#FF5519] text-white text-[15px] font-bold tracking-tight shadow-[inset_0_1px_1px_rgba(255,255,255,0.35),0_4px_12px_rgba(255,85,25,0.4)] hover:brightness-110 hover:scale-[1.02] active:scale-[0.98] transition-all duration-200 cursor-pointer"
                >
                  <span className="font-semibold text-white">Generate</span>
                  <Sparkles className="h-4 w-4 fill-white text-white shrink-0" />
                </button>
              </div>
            </div>
          </form>
        </div>
      </div>
    </>
  )
}

"use client";

import React, { useState, useEffect } from "react";
import { motion, useReducedMotion, LayoutGroup, AnimatePresence } from "motion/react";
import { Instrument_Sans } from "next/font/google";
import {
  ArrowRight,
  Check,
  Zap,
  ShieldCheck,
  GitBranch,
  Sliders
} from "lucide-react";
import { cn } from "@/lib/utils";
import { featureImg } from "./image-data";

const instrumentSans = Instrument_Sans({
  subsets: ["latin"],
});

export interface FeatureItem {
  id?: string;
  title: string;
  description: string;
  className?: string;
  visual?: React.ReactNode;
}

export interface FeaturesProps {
  badge?: string;
  title?: string;
  subtitle?: string;
  features?: FeatureItem[];
  ctaText?: string;
  onCtaClick?: () => void;
}

// ==========================================
// CARD 1: Workflow Builder Split Component
// ==========================================
function WorkflowBuilderSplit() {
  return (
    <div className={cn(instrumentSans.className, "grid grid-cols-1 lg:grid-cols-12 gap-8 p-8 sm:p-10 items-center h-full w-full")}>
      {/* Left Panel: Text & Checklist */}
      <div className="lg:col-span-5 flex flex-col justify-center h-full space-y-6">

        <div>
          <h3 className="text-2xl sm:text-3xl font-semibold tracking-tight text-zinc-900 leading-tight">
            Autonomous Workflows
          </h3>
          <p className="mt-3.5 text-zinc-500 font-medium tracking-tight text-[15px] sm:text-[16px] leading-relaxed">
            Construct, deploy, and monitor complex automated pipelines inside a clean, visual editor. Connect your API nodes in minutes with zero friction.
          </p>
        </div>

        {/* Feature List Checklist */}
        <ul className="space-y-3 pt-2">
          {[
            "Visual node-based logic constructor",
            "Real-time event logging and debugging",
            "Universal third-party API webhooks",
          ].map((item, i) => (
            <li key={i} className="flex items-center gap-3 text-zinc-600 text-sm font-medium">
              <span className="flex-shrink-0 flex items-center justify-center w-5 h-5 rounded-full bg-emerald-50 border border-emerald-100 text-emerald-600">
                <Check className="h-3 w-3" strokeWidth={3} />
              </span>
              <span>{item}</span>
            </li>
          ))}
        </ul>
      </div>

      {/* Right Panel: Showcase Image with Smoke Border GLows */}
      <div className="lg:col-span-7 relative w-full h-full flex items-center justify-center">
        <div className="relative w-full rounded-[20px] p-[2px] group">
          {/* Default Subtle Border */}
          <div className="absolute inset-0 rounded-[20px] border border-zinc-200/40 transition-opacity duration-500 group-hover:opacity-0 z-0"></div>

          {/* Solid Pink Gradient Border (Fades in on hover) */}
          <div className="absolute inset-0 rounded-[20px] bg-gradient-to-r from-pink-400 via-fuchsia-400 to-pink-400 opacity-0 group-hover:opacity-50 transition-opacity duration-500 z-0"></div>

          {/* Glowing Pink Smoke Outer Blurs (Only on hover) */}
          <div className="absolute -inset-[1px] rounded-[20px] bg-gradient-to-r from-pink-400 via-fuchsia-400 to-pink-400 blur-md opacity-0 group-hover:opacity-30 transition-opacity duration-700 z-0"></div>
          <div className="absolute -inset-[2px] rounded-[20px] bg-gradient-to-tr from-fuchsia-350 to-pink-400 blur-xl opacity-0 group-hover:opacity-20 transition-opacity duration-1000 animate-pulse z-0"></div>

          {/* The Image Container */}
